// digitalkrux.com JSON API -> src/content/episodes.json. Run by hand when a new set is out; the JSON is committed.
// The endpoint is generated by convert.cjs in the digitalkrux repo at build time (public/api/episodes.json).
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const SOURCE = process.env.EPISODES_API ?? 'https://www.digitalkrux.com/api/episodes.json';
const out = resolve(process.cwd(), 'src/content/episodes.json');

async function load(source) {
  if (!/^https?:\/\//.test(source)) return JSON.parse(readFileSync(resolve(process.cwd(), source), 'utf8'));
  const res = await fetch(source);
  if (!res.ok) throw new Error(`${source}: HTTP ${res.status}`);
  return res.json();
}

const api = await load(SOURCE);
if (!Array.isArray(api.episodes)) throw new Error(`${SOURCE}: no episodes array`);

const episodes = api.episodes
  .map((e) => {
    const { id, number, title, date, cover, audio, tracklist } = e;
    if (!id || !number || !title || !date || !audio) throw new Error(`incomplete episode: ${JSON.stringify(e).slice(0, 120)}`);
    return { id, number, title, date, cover: cover ?? null, audio, tracklist: Array.isArray(tracklist) ? tracklist : [] };
  })
  .sort((a, b) => a.number - b.number);

writeFileSync(out, JSON.stringify(episodes, null, 2) + '\n');
console.log(`${episodes.length} episodes from ${SOURCE} written to ${out}`);
